/**
 * Citation and Source Verification Service
 * 
 * Attaches source tags [S1], [S2]... to retrieved evidence chunks, builds the prompt context block,
 * and validates that citations generated by the LLM legitimately exist in the retrieved evidence.
 */

/**
 * Builds grounded context text from chunks, tagging each with [S1], [S2]...
 */
export function formatEvidenceWithTags(chunks = []) {
  if (!chunks || chunks.length === 0) {
    return {
      taggedText: 'No relevant document evidence was retrieved from the knowledge base.',
      sourceMap: new Map()
    };
  }

  const sourceMap = new Map();
  const formattedSections = chunks.map((chunk, index) => {
    const tag = `[S${index + 1}]`;
    sourceMap.set(tag, {
      tag,
      chunkId: chunk.chunkId,
      documentId: chunk.documentId,
      filename: chunk.filename,
      pageNumber: chunk.pageNumber,
      heading: chunk.heading,
      similarity: chunk.similarity,
      snippet: chunk.text.substring(0, 180) + '...'
    });

    const locationMeta = chunk.pageNumber
      ? `Page ${chunk.pageNumber}`
      : `Chunk ${chunk.chunkId || index + 1}`;

    return `${tag} Document: ${chunk.filename} (${locationMeta}) | Heading: ${chunk.heading}\n${chunk.text}`;
  });

  return {
    taggedText: formattedSections.join('\n\n---\n\n'),
    sourceMap
  };
}

/**
 * Parses and validates citations in a generated response against actual retrieved sources.
 * 
 * @param {string} responseText Raw text generated by the model
 * @param {Map<string, object>} sourceMap Map of valid [S1], [S2] source identifiers
 * @returns {object} Detailed citation validation report
 */
export function validateCitations(responseText = '', sourceMap = new Map()) {
  if (!responseText || typeof responseText !== 'string') {
    return {
      status: 'no_citation_supplied',
      validSources: [],
      invalidSources: [],
      coveragePercentage: 0,
      hasUnsupportedClaims: true
    };
  }

  // Regex to detect [S1], [S2], [S1, S2], or S1 references
  const citationRegex = /\[S(\d+)\]/gi;
  const matches = [...responseText.matchAll(citationRegex)];

  const citedTags = new Set(matches.map((m) => `[S${m[1]}]`));
  const validSources = [];
  const invalidSources = [];

  for (const tag of citedTags) {
    if (sourceMap.has(tag)) {
      validSources.push(sourceMap.get(tag));
    } else {
      invalidSources.push({ tag, reason: 'Source identifier not present in retrieved context' });
    }
  }

  const availableSourceCount = sourceMap.size;
  const coveragePercentage = availableSourceCount > 0
    ? Math.min(100, parseFloat(((validSources.length / availableSourceCount) * 100).toFixed(1)))
    : 0;

  let status = 'valid';
  let hasUnsupportedClaims = false;

  if (validSources.length === 0 && availableSourceCount > 0) {
    status = 'no_citation_supplied';
    hasUnsupportedClaims = true;
  } else if (invalidSources.length > 0) {
    status = 'invalid_references_detected';
    hasUnsupportedClaims = true;
  } else if (validSources.length < Math.min(2, availableSourceCount)) {
    status = 'unverified_citation_coverage';
  }

  return {
    status,
    validSources,
    invalidSources,
    citedTagsCount: citedTags.size,
    coveragePercentage,
    hasUnsupportedClaims
  };
}
